import React from "react";
import { createRoot } from "react-dom/client";
import AuthContainer from "./containers/AuthContainer";

import { ConfigProvider, theme } from "antd";
import antLocale_ptPT from "antd/lib/locale/pt_PT";

const authDiv = document.getElementById("app-auth");

if (authDiv) {
  const root = createRoot(authDiv);
  root.render(
    <ConfigProvider
      theme={{
        token: {
          colorPrimary: '#5b5ce1',
          colorLink: '#5b5ce1',
          borderRadius: 5,
        },
        algorithm: theme.darkAlgorithm
      }}
      locale={antLocale_ptPT}
    >
      <AuthContainer onLoginSuccess={() => {
        // Quando o login fake tiver sucesso, salta para o Backoffice do Netuno!
        window.location.href = "/Index.netuno";
      }} />
    </ConfigProvider>
  );
}
